//! D01 end-to-end vectors (`ffw-f3b`).
//!
//! `tests/d01/vectors.json` is generated by the independent Python reference
//! (`tests/d01/generate.py`), never by this crate. This harness runs every vector through the
//! public API, prints one `D01-OBSERVED {json}` line per case for the Python judge
//! (`tests/d01/run_cases.py --judge`), and also fails on any divergence, naming the first
//! divergent frame, channel and format.
//!
//! Run with `cargo test -p franken-dsp --test d01_vectors -- --nocapture` (output is needed for
//! the judge). Override the vector path with `FFW_D01_VECTORS`.

use franken_dsp::convert::{ConvertStats, convert_block};
use franken_dsp::format::{
    BufferSpec, Endian, PcmError, SampleFormat, StreamFormat, frames_in_packed_bytes,
};
use franken_dsp::ring::{BlockSink, BoundedCaptureSink, RingConsumer, ring_channel};
use serde_json::{Value, json};
use std::fmt::Write as _;

fn hex_encode(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        let _ = write!(out, "{byte:02x}");
    }
    out
}

fn hex_decode(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "odd-length hex");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digit"))
        .collect()
}

fn field<'a>(value: &'a Value, key: &str) -> &'a Value {
    value
        .get(key)
        .unwrap_or_else(|| panic!("vector field `{key}` is missing"))
}

fn str_of<'a>(value: &'a Value, key: &str) -> &'a str {
    field(value, key)
        .as_str()
        .unwrap_or_else(|| panic!("vector field `{key}` is not a string"))
}

fn usize_of(value: &Value, key: &str) -> usize {
    let n = field(value, key)
        .as_u64()
        .unwrap_or_else(|| panic!("vector field `{key}` is not an unsigned integer"));
    usize::try_from(n).unwrap_or_else(|_| panic!("vector field `{key}` does not fit usize"))
}

fn sample_format(name: &str) -> SampleFormat {
    match name {
        "s16" => SampleFormat::S16,
        "s24in32" => SampleFormat::S24In32,
        "s32" => SampleFormat::S32,
        "f32" => SampleFormat::F32,
        other => panic!("unknown sample format `{other}` in vectors"),
    }
}

fn endian(name: &str) -> Endian {
    match name {
        "big" => Endian::Big,
        "little" => Endian::Little,
        other => panic!("unknown endianness `{other}` in vectors"),
    }
}

fn stream_format(spec: &Value) -> Result<StreamFormat, PcmError> {
    StreamFormat::new(
        sample_format(str_of(spec, "format")),
        endian(str_of(spec, "endian")),
        u8::try_from(usize_of(spec, "channels")).expect("channels fits u8"),
        u32::try_from(usize_of(spec, "rate")).expect("rate fits u32"),
    )
}

fn buffer_spec(spec: &Value) -> Result<BufferSpec, PcmError> {
    let format = stream_format(spec)?;
    let stride = usize_of(spec, "stride");
    match str_of(spec, "layout") {
        "interleaved" => BufferSpec::interleaved(format, stride),
        "planar" => BufferSpec::planar(format, stride),
        other => panic!("unknown layout `{other}` in vectors"),
    }
}

fn err_json(id: &str, kind: &str, error: PcmError) -> Value {
    json!({"id": id, "kind": kind, "status": "err", "error": error.code()})
}

/// First differing byte between `observed` and `expected`, located as (frame, channel) in
/// `spec`, with the sample format. `None` when identical.
fn first_divergence(
    spec: &BufferSpec,
    frames: usize,
    observed: &[u8],
    expected: &[u8],
) -> Option<String> {
    if observed.len() != expected.len() {
        return Some(format!(
            "length differs: expected {} bytes, observed {}",
            expected.len(),
            observed.len()
        ));
    }
    let offset = observed
        .iter()
        .zip(expected.iter())
        .position(|(a, b)| a != b)?;
    let format = spec.format();
    let mut place = String::from("padding or guard byte");
    'search: for frame in 0..frames {
        for channel in 0..usize::from(format.channels()) {
            let start = spec.sample_offset(frame, channel).expect("offset");
            if (start..start + format.bytes_per_sample()).contains(&offset) {
                place = format!("frame {frame} channel {channel}");
                break 'search;
            }
        }
    }
    Some(format!(
        "first divergent byte {offset} ({place}) in {} {}: expected {:02x}, observed {:02x}",
        format.sample_format().name(),
        format.endian().name(),
        expected[offset],
        observed[offset]
    ))
}

fn stats_json(stats: ConvertStats) -> (u32, u32) {
    (stats.saturated, stats.non_finite)
}

fn run_convert(case: &Value) -> (Value, Option<String>) {
    let id = str_of(case, "id");
    let src_spec = buffer_spec(field(case, "src")).expect("src spec");
    let dst_spec = buffer_spec(field(case, "dst")).expect("dst spec");
    let frames = usize_of(case, "frames");
    let src = hex_decode(str_of(case, "src_hex"));
    let fill = u8::try_from(usize_of(case, "dst_fill")).expect("fill fits u8");
    let mut dst = vec![fill; usize_of(case, "dst_len")];
    match convert_block(&src, &src_spec, &mut dst, &dst_spec, frames) {
        Ok(stats) => {
            let (saturated, non_finite) = stats_json(stats);
            let observed = json!({"id": id, "kind": "convert", "status": "ok",
                "dst_hex": hex_encode(&dst), "saturated": saturated, "non_finite": non_finite});
            let expected = hex_decode(str_of(case, "dst_expected_hex"));
            let mut problem = first_divergence(&dst_spec, frames, &dst, &expected);
            let want = field(case, "expected");
            if problem.is_none()
                && (want["saturated"] != json!(saturated)
                    || want["non_finite"] != json!(non_finite))
            {
                problem = Some(format!(
                    "stats differ: expected {want}, observed saturated={saturated} non_finite={non_finite}"
                ));
            }
            (observed, problem)
        }
        Err(e) => (
            err_json(id, "convert", e),
            Some(format!("unexpected error {}", e.code())),
        ),
    }
}

/// Compare an `{ok|error}` outcome against the vector's `expect`.
fn outcome(
    id: &str,
    kind: &str,
    result: Result<Value, PcmError>,
    expect: &Value,
) -> (Value, Option<String>) {
    match result {
        Ok(detail) => {
            let mut observed = json!({"id": id, "kind": kind, "status": "ok"});
            if let (Some(target), Some(extra)) = (observed.as_object_mut(), detail.as_object()) {
                for (k, v) in extra {
                    target.insert(k.clone(), v.clone());
                }
            }
            let problem = match expect.get("error") {
                Some(code) => Some(format!("expected error {code}, observed success")),
                None => expect
                    .as_object()
                    .and_then(|want| {
                        want.iter()
                            .filter(|(k, _)| k.as_str() != "ok")
                            .find(|(k, v)| observed.get(k.as_str()) != Some(*v))
                    })
                    .map(|(k, v)| format!("expected {k}={v}, observed {observed}")),
            };
            (observed, problem)
        }
        Err(e) => {
            let observed = err_json(id, kind, e);
            let problem = match expect.get("error").and_then(Value::as_str) {
                Some(code) if code == e.code() => None,
                Some(code) => Some(format!("expected error {code}, observed {}", e.code())),
                None => Some(format!("expected success, observed error {}", e.code())),
            };
            (observed, problem)
        }
    }
}

fn run_convert_error(case: &Value) -> (Value, Option<String>) {
    let id = str_of(case, "id");
    let src_spec = buffer_spec(field(case, "src")).expect("src spec");
    let dst_spec = buffer_spec(field(case, "dst")).expect("dst spec");
    let src = vec![0u8; usize_of(case, "src_len")];
    let mut dst = vec![0u8; usize_of(case, "dst_len")];
    let result = convert_block(
        &src,
        &src_spec,
        &mut dst,
        &dst_spec,
        usize_of(case, "frames"),
    )
    .map(|_| json!({}));
    outcome(id, "convert_error", result, field(case, "expect"))
}

fn run_packed_len(case: &Value) -> (Value, Option<String>) {
    let id = str_of(case, "id");
    let format = stream_format(field(case, "format")).expect("format");
    let result = frames_in_packed_bytes(usize_of(case, "len"), &format)
        .map(|frames| json!({"frames": frames}));
    outcome(id, "packed_len", result, field(case, "expect"))
}

fn run_spec(case: &Value) -> (Value, Option<String>) {
    let id = str_of(case, "id");
    let spec = field(case, "spec");
    let result: Result<Value, PcmError> = match str_of(case, "op") {
        "format" => stream_format(spec).map(|f| json!({"bytes_per_frame": f.bytes_per_frame()})),
        "stride" => buffer_spec(spec).map(|_| json!({})),
        "required_len" => buffer_spec(spec)
            .and_then(|s| s.required_len(usize_of(case, "frames")))
            .map(|len| json!({"len": len})),
        other => panic!("unknown spec op `{other}`"),
    };
    outcome(id, "spec", result, field(case, "expect"))
}

fn run_ring(case: &Value) -> (Value, Option<String>) {
    let id = str_of(case, "id");
    let format = stream_format(field(case, "format")).expect("format");
    let (mut producer, mut consumer) =
        ring_channel(format, usize_of(case, "capacity")).expect("ring");
    let mut results: Vec<Value> = Vec::new();
    for op in field(case, "ops").as_array().expect("ops array") {
        let name = op[0].as_str().expect("op name");
        let result = match name {
            "push" => {
                let block = hex_decode(op[1].as_str().expect("push hex"));
                match producer.push(&block) {
                    Ok(frames) => json!({"ok": frames, "avail": consumer.available_frames()}),
                    Err(e) => json!({"error": e.code(), "avail": consumer.available_frames()}),
                }
            }
            "pop" => {
                let len = usize::try_from(op[1].as_u64().expect("pop length")).expect("usize");
                let mut out = vec![0u8; len];
                match consumer.pop(&mut out) {
                    Ok(frames) => json!({"ok": frames, "hex": hex_encode(&out),
                        "avail": consumer.available_frames()}),
                    Err(e) => json!({"error": e.code(), "avail": consumer.available_frames()}),
                }
            }
            other => panic!("unknown ring op `{other}`"),
        };
        results.push(result);
    }
    let expect = field(case, "expect").as_array().expect("expect array");
    let problem = results
        .iter()
        .zip(expect.iter())
        .position(|(got, want)| got != want)
        .map(|step| {
            format!(
                "ring step {step} {}: expected {}, observed {}",
                field(case, "ops")[step][0],
                expect[step],
                results[step]
            )
        })
        .or_else(|| {
            (results.len() != expect.len()).then(|| {
                format!(
                    "expected {} steps, observed {}",
                    expect.len(),
                    results.len()
                )
            })
        });
    (
        json!({"id": id, "kind": "ring", "results": results}),
        problem,
    )
}

/// Consumer side of the pipeline schedule: pop one chunk, convert it, hand it to the sink.
struct Drain {
    consumer: RingConsumer,
    ring_spec: BufferSpec,
    out_spec: BufferSpec,
    pop_scratch: Vec<u8>,
    out_scratch: Vec<u8>,
    sink: BoundedCaptureSink,
    stats: ConvertStats,
}

impl Drain {
    fn one(&mut self, frames: usize) -> Result<(), PcmError> {
        let ring_len = frames * self.ring_spec.format().bytes_per_frame();
        let out_len = frames * self.out_spec.format().bytes_per_frame();
        self.consumer.pop(&mut self.pop_scratch[..ring_len])?;
        let stats = convert_block(
            &self.pop_scratch[..ring_len],
            &self.ring_spec,
            &mut self.out_scratch,
            &self.out_spec,
            frames,
        )?;
        self.stats.merge(stats);
        self.sink.write_block(&self.out_scratch[..out_len])
    }
}

fn run_pipeline(case: &Value) -> (Value, Option<String>) {
    let id = str_of(case, "id");
    let src_spec = buffer_spec(field(case, "src")).expect("src spec");
    let ring_spec = buffer_spec(field(case, "ring")).expect("ring spec");
    let out_spec = buffer_spec(field(case, "out")).expect("out spec");
    let (block, lag) = (usize_of(case, "block_frames"), usize_of(case, "lag"));
    let src = hex_decode(str_of(case, "src_hex"));
    let src_bpf = src_spec.format().bytes_per_frame();
    let ring_bpf = ring_spec.format().bytes_per_frame();
    let out_bpf = out_spec.format().bytes_per_frame();
    let total = src.len() / src_bpf;
    let sizes: Vec<usize> = (0..total)
        .step_by(block)
        .map(|start| block.min(total - start))
        .collect();

    let (mut producer, consumer) =
        ring_channel(*ring_spec.format(), usize_of(case, "ring_frames")).expect("ring");
    let mut ring_scratch = vec![0u8; block * ring_bpf];
    let mut drain = Drain {
        consumer,
        ring_spec,
        out_spec,
        pop_scratch: vec![0u8; block * ring_bpf],
        out_scratch: vec![0u8; block * out_bpf],
        sink: BoundedCaptureSink::with_capacity(total * out_bpf),
        stats: ConvertStats::default(),
    };

    let mut stats = ConvertStats::default();
    let mut run = || -> Result<(), PcmError> {
        let (mut start, mut popped) = (0usize, 0usize);
        for (k, &n) in sizes.iter().enumerate() {
            stats.merge(convert_block(
                &src[start * src_bpf..(start + n) * src_bpf],
                &src_spec,
                &mut ring_scratch,
                &drain.ring_spec,
                n,
            )?);
            producer.push(&ring_scratch[..n * ring_bpf])?;
            start += n;
            if k >= lag {
                drain.one(sizes[popped])?;
                popped += 1;
            }
        }
        while popped < sizes.len() {
            drain.one(sizes[popped])?;
            popped += 1;
        }
        Ok(())
    };
    if let Err(e) = run() {
        return (
            err_json(id, "pipeline", e),
            Some(format!("pipeline failed with {}", e.code())),
        );
    }
    stats.merge(drain.stats);
    let (saturated, non_finite) = stats_json(stats);
    let out = drain.sink.as_bytes();
    let observed = json!({"id": id, "kind": "pipeline", "status": "ok", "out_hex": hex_encode(out),
        "saturated": saturated, "non_finite": non_finite});
    let expected = hex_decode(str_of(case, "out_expected_hex"));
    let mut problem = first_divergence(&drain.out_spec, total, out, &expected);
    let want = field(case, "expected");
    if problem.is_none()
        && (want["saturated"] != json!(saturated) || want["non_finite"] != json!(non_finite))
    {
        problem = Some(format!(
            "stats differ: expected {want}, observed saturated={saturated} non_finite={non_finite}"
        ));
    }
    (observed, problem)
}

fn run_case(case: &Value) -> (Value, Option<String>) {
    match str_of(case, "kind") {
        "convert" => run_convert(case),
        "convert_error" => run_convert_error(case),
        "packed_len" => run_packed_len(case),
        "spec" => run_spec(case),
        "ring" => run_ring(case),
        "pipeline" => run_pipeline(case),
        other => panic!("unknown vector kind `{other}`"),
    }
}

fn load_vectors() -> Value {
    let path = std::env::var("FFW_D01_VECTORS").unwrap_or_else(|_| {
        format!(
            "{}/../../tests/d01/vectors.json",
            env!("CARGO_MANIFEST_DIR")
        )
    });
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!("cannot read D01 vectors at {path}: {e} (generate: tests/d01/run_cases.py --write-vectors)")
    });
    let doc: Value = serde_json::from_str(&text).expect("vectors.json parses");
    assert_eq!(doc["schema"], "ffw.d01.vectors.v1");
    doc
}

#[test]
fn d01_vectors_match_the_independent_reference() {
    let doc = load_vectors();
    let cases = doc["cases"].as_array().expect("cases array");
    assert!(
        cases.len() >= 100,
        "suspiciously few vectors: {}",
        cases.len()
    );
    let mut failures: Vec<String> = Vec::new();
    for case in cases {
        let (observed, problem) = run_case(case);
        println!("D01-OBSERVED {observed}");
        if let Some(message) = problem {
            let line = format!("{}: {message}", str_of(case, "id"));
            println!("D01-DIVERGENCE {line}");
            failures.push(line);
        }
    }
    println!(
        "D01-SUMMARY cases={} failures={}",
        cases.len(),
        failures.len()
    );
    assert!(
        failures.is_empty(),
        "{} of {} D01 vectors diverged from the reference; first: {}",
        failures.len(),
        cases.len(),
        failures[0]
    );
}

/// Control: the comparison is not vacuous. Corrupt one expected byte in a copy of a real vector
/// and the harness must report a divergence at the right place.
#[test]
fn a_planted_corruption_is_detected_and_located() {
    let doc = load_vectors();
    let cases = doc["cases"].as_array().expect("cases array");
    let case = cases
        .iter()
        .find(|c| str_of(c, "id") == "D01-CONV-s16-big__s32-little")
        .expect("matrix case present");
    assert!(
        run_case(case).1.is_none(),
        "the unmodified vector must pass"
    );

    // s32 little-endian stereo: byte 5 is the second byte of frame 0, channel 1.
    let mut corrupted = case.clone();
    let mut expected = hex_decode(str_of(case, "dst_expected_hex"));
    expected[5] ^= 0x01;
    corrupted["dst_expected_hex"] = json!(hex_encode(&expected));
    let problem = run_case(&corrupted).1.expect("corruption must be detected");
    assert!(problem.contains("frame 0 channel 1"), "{problem}");
    assert!(problem.contains("s32 little"), "{problem}");
    assert!(problem.contains("byte 5"), "{problem}");
}

/// Control: a divergence inside padding is reported as padding, and later frames are located.
#[test]
fn divergence_report_names_frame_channel_format_and_padding() {
    let format = StreamFormat::new(SampleFormat::S16, Endian::Big, 2, 48_000).unwrap();
    let spec = BufferSpec::interleaved(format, 8).unwrap(); // 4 bytes of padding per frame
    let expected = vec![0u8; 20];
    assert_eq!(first_divergence(&spec, 3, &expected, &expected), None);

    let mut observed = expected.clone();
    observed[8 + 2] = 0x7F; // frame 1, channel 1 (bytes 10..12)
    let message = first_divergence(&spec, 3, &observed, &expected).expect("divergence");
    assert!(message.contains("frame 1 channel 1"), "{message}");
    assert!(message.contains("s16 big"), "{message}");

    let mut in_padding = expected.clone();
    in_padding[5] = 0x01; // between frame 0 and frame 1
    let message = first_divergence(&spec, 3, &in_padding, &expected).expect("divergence");
    assert!(message.contains("padding or guard byte"), "{message}");

    let shorter = first_divergence(&spec, 3, &expected[..19], &expected).expect("length");
    assert!(shorter.contains("length differs"), "{shorter}");
}
